  "definitions": [
    {
      "tag": "vm.run",
      "meaning": "Create and cold-start a workload with this engine and storage"
    },
    {
      "tag": "net.tcp.publish",
      "meaning": "Publish TCP guest ports on the agent host"
    },
    {
      "tag": "guest.ssh.bootstrap",
      "meaning": "Initialize an SSH account and report its access metadata"
    },
    {
      "tag": "guest.ssh.root_keys",
      "meaning": "Inject root authorized keys without managed SSH bootstrap"
    },
    {
      "tag": "guest.config.drive",
      "meaning": "Deliver caller-supplied opaque files on a read-only guest drive"
    },
    {
      "tag": "net.egress.deny",
      "meaning": "Block new routed guest egress while preserving incoming replies"
    },
    {
      "tag": "net.isolation",
      "meaning": "Enforce guest isolation from host, peers and private networks"
    },
    {
      "tag": "disk.size.create",
      "meaning": "Request virtual root-disk capacity at creation"
    },
    {
      "tag": "vm.resources.offline",
      "meaning": "Update CPU, memory and root-disk capacity while stopped"
    },
    {
      "tag": "disk.backup.point",
      "meaning": "Create a stopped root-disk recovery point using a qualified primitive"
    }
  ],
